import type {
  EngineInterface,
  Register,
  SessionUsage,
  TurnStepInput,
  TurnStepResult,
} from "claude-code";
import {
  bar,
  cacheNote,
  carryCost,
  costAt,
  crossed,
  describeSwitch,
  duration,
  effortFor,
  EXPIRY_TOAST_MS,
  EXPIRY_TOAST_USD,
  fiveHour,
  type Handoff,
  handoffBlock,
  handoffFile,
  handoffFor,
  HANDOFF_PROMPT,
  inProject,
  isWindow,
  kTokens,
  LONG_CONTEXT,
  meterColor,
  meterText,
  modelLabel,
  type Override,
  parseOverrides,
  PAYBACK_REQUESTS,
  paybackRequests,
  percent,
  projectName,
  record,
  reloadCost,
  SAVED_MILESTONES,
  savedBy,
  sevenDay,
  share,
  sparkline,
  summary,
  switchFor,
  turnLine,
  usd,
  type Tokens,
  type Window,
  WINDOW_ALERTS,
  windowNote,
  windowShare,
  windowsOf,
} from "./meter.ts";

// The optimAIzr mod: this turn's cost and the 5-hour window while Claude works,
// one line under each answer, the model and effort switches `optimaizr live`
// accepts, a guard against retry loops, and a countdown before the cache expires.
// It reads usage figures and the commands Claude runs, never prompt text or file
// contents. The one text it keeps is the note /optimaizr handoff asks Claude for.

const VERSION = "0.10.1";
// The HUD /optimaizr hud opens beside the conversation.
const PANE = "optimaizr";
// overrides.json is read again at most this often, so `optimaizr undo` lands fast.
const REREAD_MS = 3_000;
// `optimaizr live` counts a session as gone after three missed beats.
const BEAT_MS = 60_000;
// Claude Code caches the main conversation for an hour; after that a reload is paid either way.
const CACHE_TTL_MS = 55 * 60_000;
// A command that failed this many times in a row, unchanged, is held once.
const RETRY_LIMIT = 2;

// Tools whose success can change what a retried command sees.
const MUTATING = new Set(["Edit", "Write", "MultiEdit", "NotebookEdit", "Bash"]);

type Api = EngineInterface;

type Turn = {
  startUsd: number;
  startPct?: number;
  calls: number;
  switched?: Override;
  saved?: number;
  effort?: string;
  held: number;
};

// One session's figures, shared by the hooks below.
const state = {
  dir: "",
  file: "",
  id: "",
  // The project root: where the session started. A shell `cd` doesn't move it.
  root: "",
  startedAt: 0,
  requests: 0,
  usage: null as SessionUsage | null,
  window: undefined as Window | undefined,
  turn: null as Turn | null,
  overrides: [] as Override[],
  readAt: -Infinity,
  // Switches that moved at least one request in this session, by slot.
  applied: new Map<string, Override>(),
  // Targets the API refused here; the session keeps its own setting for them.
  refused: new Set<string>(),
  // `/optimaizr off`: this session goes back to its own model until `/optimaizr on`.
  paused: false,
  // Switches the person has been told about, so the note shows once.
  told: new Set<string>(),
  // Net saving of the switched requests, once one has been priced.
  saved: undefined as number | undefined,
  held: 0,
  // The session's average unswitched main request, which a switch is weighed against.
  avg: { n: 0, input: 0, output: 0, read: 0, write: 0 },
  // When the main conversation last made a request; past the cache's lifetime, it reloads anyway.
  lastMainAt: null as number | null,
  // The model that request went to, whose cache holds the conversation.
  model: "",
  // Counts /clear and /resume, so a handoff note is never read back where it was written.
  conversation: 0,
  // The idle stretch, by its last request, already warned about the cache expiring.
  expiryTold: null as number | null,
  // A main-conversation switch held back because its reload wouldn't pay back yet.
  waiting: null as { o: Override; reload: number; payback: number } | null,
  // Token totals since the mod loaded, for the cache-hit share.
  tokens: { input: 0, read: 0, write: 0 },
  // What switched requests cost, and what they would have cost unswitched.
  switchedWas: 0,
  switchedIs: 0,
  // Session cost and 5-hour reading when the mod loaded, for the burn rate and window share.
  startUsd: null as number | null,
  startPct: null as number | null,
  // What each finished turn cost, newest last, for the pane's sparkline.
  turnCosts: [] as number[],
  // Window levels already toasted, by reset time.
  warned: new Set<string>(),
  // What this conversation has seen; compaction and /clear forget it.
  convo: {
    // Models that already wrote this conversation to their cache.
    loaded: new Set<string>(),
    fails: new Map<string, number>(),
    // Held once already: the next identical command goes through.
    waived: new Set<string>(),
    // The handoff block this conversation started from, kept so a re-read gets the same one.
    handoff: null as string | null,
    // Told once that the conversation passed LONG_CONTEXT.
    long: false,
  },
};

function forget(): void {
  state.convo = {
    loaded: new Set(),
    fails: new Map(),
    waived: new Set(),
    handoff: null,
    long: false,
  };
}

async function optimaizrDir($: Api): Promise<string> {
  const set = await $.env.get("OPTIMAIZR_DIR");
  if (set) return set;
  const home = (await $.env.get("HOME")) ?? (await $.env.get("USERPROFILE")) ?? ".";
  return `${home}/.optimaizr`;
}

/** Keep the latest usage, add a 5-hour reading to the shared history, redraw. */
async function take($: Api, u: SessionUsage): Promise<void> {
  const was = fiveHour(state.usage?.rateLimits)?.percentUsed;
  state.usage = u;
  const five = fiveHour(u.rateLimits);
  if (five && was !== undefined) {
    const level = crossed(WINDOW_ALERTS, was, five.percentUsed);
    const key = `${five.resetsAt ?? ""}:${level}`;
    if (level !== null && !state.warned.has(key)) {
      state.warned.add(key);
      void $.ui.toast(
        `optimAIzr: 5h window at ${percent(five.percentUsed)}${windowNote(five, state.window, await $.clock.now())}`,
        { timeoutMs: 8_000 },
      );
    }
  }
  // The CLI reads the meters from the session file, so a move is written at once.
  if (five && five.percentUsed !== was) await beat($).catch(() => undefined);
  if (five) {
    const stored = await $.store.get("window");
    const prev = isWindow(stored) ? stored : state.window;
    const next = record(prev, five, await $.clock.now());
    state.window = next;
    if (next !== prev) await $.store.set("window", next);
  }
  void $.ui.invalidate("ui.render");
}

async function measure($: Api): Promise<void> {
  await take($, await $.session.usage());
}

/** The session file `optimaizr live` and `optimaizr mod` read. */
async function beat($: Api, ended = false): Promise<void> {
  if (!state.file) return;
  const at = await $.clock.now();
  const now = new Date(at).toISOString();
  const windows = windowsOf(state.usage?.rateLimits, at);
  const body = {
    id: state.id,
    version: VERSION,
    cwd: state.root,
    startedAt: new Date(state.startedAt).toISOString(),
    seenAt: now,
    ...(ended ? { endedAt: now } : {}),
    ...(windows ? { windows } : {}),
  };
  await $.fs.write(state.file, `${JSON.stringify(body)}\n`);
}

/** Once a minute: tell the CLI the session is alive, and notice an undo while idle. */
async function refresh($: Api): Promise<void> {
  await beat($).catch(() => undefined);
  await switches($).catch(() => undefined);
  await expiring($).catch(() => undefined);
  void $.ui.invalidate("ui.render");
}

/** What to say about the main conversation's cache while the prompt waits. */
async function cacheNow($: Api): Promise<{ label: string; text: string } | null> {
  if (state.turn || state.lastMainAt === null || !state.model) return null;
  return cacheNote({
    model: state.model,
    context: state.usage?.context.tokens ?? 0,
    idleMs: (await $.clock.now()) - state.lastMainAt,
    ttlMs: CACHE_TTL_MS,
  });
}

/** One toast shortly before an idle conversation's cache expires, when coming back would cost. */
async function expiring($: Api): Promise<void> {
  const at = state.lastMainAt;
  if (at === null || state.turn || state.expiryTold === at) return;
  const left = at + CACHE_TTL_MS - (await $.clock.now());
  const context = state.usage?.context.tokens ?? 0;
  const cost = carryCost(state.model, context);
  if (left <= 0 || left > EXPIRY_TOAST_MS || !cost || cost.rewrite < EXPIRY_TOAST_USD) return;
  state.expiryTold = at;
  void $.ui.toast(
    `optimAIzr: the cache expires in ${duration(left)}. Coming back after that writes ${kTokens(context)} again (${usd(cost.rewrite)}). Leaving? /optimaizr handoff, then /clear.`,
    { timeoutMs: 10_000 },
  );
}

/** /optimaizr handoff: Claude writes a note from the warm cache, kept for the next conversation here. */
async function handoff($: Api): Promise<string> {
  if (state.turn) return "Claude is still working. Run /optimaizr handoff once the turn ends.";
  const r = await $.model.fork({ prompt: HANDOFF_PROMPT });
  if (!r.isAnswered) {
    if (r.reason === "nothing-to-fork") {
      return "Nothing to hand off yet: Claude hasn't answered in this conversation.";
    }
    if (r.reason === "api-error") {
      return `Couldn't write the note: the API answered ${r.status ?? "nothing"} (${r.error}). Try again in a moment.`;
    }
    return r.reason === "aborted"
      ? "The note was cancelled."
      : "Claude answered without a note. Try again.";
  }
  const now = await $.clock.now();
  const note: Handoff = {
    version: 1,
    root: state.root,
    session: state.id,
    conversation: state.conversation,
    at: new Date(now).toISOString(),
    text: r.text.trim(),
  };
  await $.fs.write(handoffFile(state.dir, state.root), `${JSON.stringify(note, null, 2)}\n`);

  // Mostly read from cache, it cost little; otherwise the cache had expired.
  const u = r.usage;
  const cost = costAt(state.model, u, { hour: true });
  const warm = u.cache_read_input_tokens >= u.input_tokens + u.cache_creation_input_tokens;
  const how =
    cost === null
      ? ""
      : warm
        ? `, written from the warm cache for ${usd(cost)}`
        : `, for ${usd(cost)}: the cache had expired, so Claude read the conversation again`;
  return (
    `Handoff saved for ${projectName(state.root)}${how}.\n\n${note.text}\n\n` +
    `/clear now and the next conversation in this project starts from this note. ` +
    `It is used once, within 12 hours.`
  );
}

/** The handoff note a new conversation here starts from, claimed once. */
async function startFrom($: Api): Promise<string | null> {
  if (state.convo.handoff !== null) return state.convo.handoff;
  const dir = state.dir || (await optimaizrDir($));
  const root = state.root || (await $.session.root());
  const file = handoffFile(dir, root);
  const text = await $.fs.read(file).catch(() => "");
  let stored: unknown = null;
  try {
    stored = JSON.parse(typeof text === "string" ? text : "");
  } catch {
    return null;
  }
  const now = await $.clock.now();
  const h = handoffFor(stored, {
    root,
    session: state.id,
    conversation: state.conversation,
    now,
  });
  if (!h) return null;
  await $.fs.write(
    file,
    `${JSON.stringify({ ...h, usedAt: new Date(now).toISOString() }, null, 2)}\n`,
  );
  state.convo.handoff = handoffBlock(h);
  void $.ui.toast("optimAIzr: this conversation starts from your handoff note", {
    timeoutMs: 6_000,
  });
  return state.convo.handoff;
}

async function switches($: Api): Promise<Override[]> {
  const now = await $.clock.now();
  if (now - state.readAt < REREAD_MS) return state.overrides;
  state.readAt = now;
  const text = await $.fs.read(`${state.dir}/overrides.json`).catch(() => "");
  state.overrides = parseOverrides(typeof text === "string" ? text : "");
  return state.overrides;
}

/** Fold an unswitched main request into the session's average. */
function learn(u: Tokens): void {
  const a = state.avg;
  a.n += 1;
  a.input += (u.input_tokens - a.input) / a.n;
  a.output += (u.output_tokens - a.output) / a.n;
  a.read += (u.cache_read_input_tokens - a.read) / a.n;
  a.write += (u.cache_creation_input_tokens - a.write) / a.n;
}

/** The average request, or a modest one before there is any to go on. */
function average(contextTokens: number): Tokens {
  const a = state.avg;
  return a.n > 0
    ? {
        input_tokens: a.input,
        output_tokens: a.output,
        cache_read_input_tokens: a.read,
        cache_creation_input_tokens: a.write,
      }
    : {
        input_tokens: 0,
        output_tokens: 500,
        cache_read_input_tokens: contextTokens,
        cache_creation_input_tokens: 1_000,
      };
}

/** Count a finished request and refresh the figures the spinner shows. */
async function counted($: Api, u?: Tokens | null): Promise<void> {
  if (u) {
    state.tokens.input += u.input_tokens;
    state.tokens.read += u.cache_read_input_tokens;
    state.tokens.write += u.cache_creation_input_tokens;
  }
  state.requests += 1;
  if (state.turn) state.turn.calls += 1;
  await measure($).catch(() => undefined);
}

const slotOf = (o: Override) =>
  `${o.project}\u0000${o.subagent ?? ""}\u0000${o.from}\u0000${o.effort ?? ""}`;

// No response and no usage, and not because the person interrupted: the request failed.
const failed = (r: TurnStepResult, aborted: boolean) =>
  !aborted && r.stopReason === null && r.usage === null;

const clip = (s: string, n = 60) => (s.length > n ? `${s.slice(0, n - 3)}...` : s);

const commandKey = (agent: string, command: string) =>
  `${agent}\u0000${command.trim().replace(/\s+/g, " ")}`;

export const register: Register = (on, options) => {
  const showTurnLine = options.turnLine !== false;
  const retryGuard = options.retryGuard !== false;

  on("session.start", async ($, e, next) => {
    state.dir = await optimaizrDir($);
    state.id = await $.session.id();
    state.root = await $.session.root();
    state.startedAt = await $.clock.now();
    state.file = `${state.dir}/mod/sessions/${state.id}.json`;
    await $.command.register({
      name: "optimaizr",
      description:
        "This session's spend, savings and plan windows; hud opens the HUD, handoff saves a note to start fresh from, off or on pauses a switch",
      argumentHint: "[hud|handoff|off|on]",
      immediate: true,
    });
    await beat($).catch(() => undefined);
    $.clock.every(BEAT_MS, () => void refresh($));
    await measure($).catch(() => undefined);
    state.startUsd = state.usage?.cost?.usd ?? null;
    state.startPct = fiveHour(state.usage?.rateLimits)?.percentUsed ?? null;
    return next(e);
  });

  // /clear and /resume end a conversation, not the session the mod runs in.
  on("session.end", async ($, e, next) => {
    forget();
    if (e.reason === "clear" || e.reason === "resume") {
      state.conversation += 1;
      state.lastMainAt = null;
    } else {
      await beat($, true).catch(() => undefined);
    }
    return next(e);
  });

  // A new conversation in a project with a waiting handoff note starts from it, once.
  on("prompt.context", async ($, e, next) => {
    const r = await next(e);
    const text = await startFrom($).catch(() => null);
    return text ? { ...r, blocks: [...r.blocks, { name: "optimaizrHandoff", text }] } : r;
  });

  // After compaction the conversation is new to every model's cache.
  on("session.compact", async ($, e, next) => {
    forget();
    return next(e);
  });

  on("session.measure", async ($, e, next) => {
    await take($, { context: e.context, rateLimits: e.rateLimits, cost: e.cost }).catch(
      () => undefined,
    );
    return next(e);
  });

  on("turn.start", async ($, e, next) => {
    await measure($).catch(() => undefined);
    state.turn = {
      startUsd: state.usage?.cost?.usd ?? 0,
      startPct: fiveHour(state.usage?.rateLimits)?.percentUsed,
      calls: 0,
      held: 0,
    };
    return next(e);
  });

  on("turn.step", async function* ($, e, next) {
    const req = {
      cwd: state.root,
      model: e.model,
      subagent: e.agentId !== undefined,
      ...(e.effort !== undefined ? { effort: e.effort } : {}),
    };
    const list = state.paused ? [] : await switches($).catch(() => []);
    const sw = switchFor(list, req);
    let model = sw && !state.refused.has(sw.to) ? sw : undefined;

    // A conversation under way switches only once reloading it pays back soon.
    // Subagents start with an empty cache, so they always switch.
    const now = await $.clock.now();
    const cold = state.lastMainAt !== null && now - state.lastMainAt > CACHE_TTL_MS;
    if (model && e.agentId === undefined && !state.convo.loaded.has(model.to) && !cold) {
      const context = state.usage?.context.tokens ?? 0;
      const payback = paybackRequests(model, context, average(context));
      if (payback > PAYBACK_REQUESTS) {
        state.waiting = { o: model, reload: reloadCost(model, context) ?? 0, payback };
        model = undefined;
      } else {
        state.waiting = null;
      }
    }
    if (e.agentId === undefined) {
      state.lastMainAt = now;
      state.model = model?.to ?? e.model;
    }
    const ef = model ? undefined : effortFor(list, req);
    const effort = ef && !state.refused.has(`effort:${ef.effort}`) ? ef : undefined;
    const o = model ?? effort;
    if (!o) {
      const r = yield* next(e);
      // A request that rewrote an expired cache would make every request look costly.
      if (e.agentId === undefined && r.usage && !cold) learn(r.usage);
      await counted($, r.usage);
      return r;
    }

    // Stream the switched request through by hand, to know whether any of it
    // arrived before deciding it failed.
    const stream = next(
      model ? { ...e, model: model.to } : { ...e, effort: o.effort as TurnStepInput["effort"] },
    );
    let arrived = false;
    let result: TurnStepResult | undefined;
    try {
      for (;;) {
        const step = await stream.next();
        if (step.done) {
          result = step.value;
          break;
        }
        arrived = true;
        yield step.value;
      }
    } catch (err) {
      if (arrived || next.signal.aborted) throw err;
    }
    if (result && (arrived || !failed(result, next.signal.aborted))) {
      state.applied.set(slotOf(o), o);
      if (model && result.usage) {
        // Only a warm main conversation has a cache to reload; a subagent, or a
        // conversation idle past the cache's lifetime, writes it on either model.
        const main = e.agentId === undefined;
        const first = main && !cold && !state.convo.loaded.has(model.to);
        if (main) state.convo.loaded.add(model.to);
        const saved = savedBy(model, result.usage, first, e.agentId === undefined);
        const was = costAt(model.from, result.usage, { warm: first, hour: main });
        const is = costAt(model.to, result.usage, { hour: main });
        if (was !== null && is !== null) {
          state.switchedWas += was;
          state.switchedIs += is;
        }
        const before = state.saved ?? 0;
        if (saved !== null) state.saved = before + saved;
        const milestone = crossed(SAVED_MILESTONES, before, state.saved ?? 0);
        if (milestone !== null) {
          void $.ui.toast(`optimAIzr: saved ${usd(state.saved ?? 0)} this session by switching`, {
            timeoutMs: 6_000,
          });
        }
        if (state.turn && saved !== null) state.turn.saved = (state.turn.saved ?? 0) + saved;
      }
      if (state.turn && model) state.turn.switched = model;
      if (state.turn && !model) state.turn.effort = o.effort;
      // Subagents and the main conversation are told apart: either can switch first.
      const sub = e.agentId !== undefined;
      const told = `${slotOf(o)}\u0000${sub ? "sub" : "main"}`;
      if (!state.told.has(told)) {
        state.told.add(told);
        $.ui.log(switchNote(o, sub));
        if (o.auto) {
          void $.ui.toast(
            `optimAIzr: ${o.effort ? `lowered effort to ${o.effort}` : `switched to ${modelLabel(o.to)}`} automatically · p or /optimaizr off undoes`,
            { timeoutMs: 8_000 },
          );
        }
      }
      await counted($, result.usage);
      return result;
    }

    // Refused before a word came back: send the request as it was, and leave
    // this target alone for the rest of the session.
    state.refused.add(model ? model.to : `effort:${o.effort}`);
    void $.ui.toast(
      model
        ? `optimAIzr: ${modelLabel(model.to)} was refused, staying on ${modelLabel(e.model)}`
        : `optimAIzr: ${o.effort} effort was refused, staying at ${String(e.effort)}`,
    );
    const r = yield* next(e);
    await counted($);
    return r;
  });

  on("tool.call", async ($, e, next) => {
    const agent = e.agentId ?? "main";
    const c = state.convo;

    if (retryGuard && e.tool === "Bash") {
      const key = commandKey(agent, e.command);
      if ((c.fails.get(key) ?? 0) >= RETRY_LIMIT && !c.waived.has(key)) {
        c.waived.add(key);
        state.held += 1;
        if (state.turn) state.turn.held += 1;
        $.ui.log(
          `Held a retry of \`${clip(e.command.trim())}\`: it failed twice in a row with nothing changed in between.`,
        );
        return {
          deny:
            "optimAIzr held this retry: the same command failed twice in a row and nothing has changed since. " +
            "Change something first (the command, the code or the setup), or tell the user what is blocking you. " +
            "If it must run unchanged, run it again and it will go through.",
        };
      }
    }

    const ran = await next(e);
    const ok = ran.deny === undefined && ran.isError !== true;
    if (e.tool === "Bash" && ran.isError === true) {
      const key = commandKey(agent, e.command);
      c.fails.set(key, (c.fails.get(key) ?? 0) + 1);
    }
    if (ok && MUTATING.has(e.tool)) {
      c.fails.clear();
      c.waived.clear();
    }
    return ran;
  });

  on("turn.complete", async ($, e, next) => {
    const r = await next(e);
    if (e.agentId !== undefined) return r;
    const t = state.turn;
    state.turn = null;
    void $.ui.invalidate("ui.render");
    if (!t || e.reason !== "answer") return r;

    await measure($).catch(() => undefined);
    longNote($);
    const spent = (state.usage?.cost?.usd ?? 0) - t.startUsd;
    state.turnCosts = [...state.turnCosts, Math.max(0, spent)].slice(-24);
    if (!showTurnLine || spent < 0.005) return r;
    const after = fiveHour(state.usage?.rateLimits)?.percentUsed;
    const line = turnLine({
      usd: spent,
      calls: t.calls,
      ...(t.switched
        ? {
            switched: {
              from: modelLabel(t.switched.from),
              to: modelLabel(t.switched.to),
              saved: t.saved ?? null,
            },
          }
        : {}),
      ...(t.effort ? { effort: t.effort } : {}),
      held: t.held,
      ...(t.startPct !== undefined ? { before: t.startPct } : {}),
      ...(after !== undefined ? { after } : {}),
    });
    return { ...r, text: line };
  });

  on("ui.render", { component: "Spinner" }, async ($, e, next) => {
    const t = state.turn;
    const extra = meterText({
      usd: t ? (state.usage?.cost?.usd ?? 0) - t.startUsd : null,
      five: fiveHour(state.usage?.rateLimits),
      ...(t?.switched ? { model: modelLabel(t.switched.to) } : {}),
      ...(t?.saved !== undefined ? { saved: t.saved } : {}),
    });
    if (!extra) return next(e);
    return next({ ...e, props: { ...e.props, suffix: `${extra}${e.props.suffix}` } });
  });

  on("ui.render", { component: "AbovePrompt" }, async ($, e, next) => {
    const u = state.usage;
    if (e.props.hasSurvey || !u) return next(e);
    const { Box, Text } = $.ui.resolve(e);
    const five = fiveHour(u.rateLimits);
    const waiting = waitingNote();
    const cache = e.props.isWorking ? null : await cacheNow($);
    const lines = [
      ...switchLines(activeSwitches()),
      ...(waiting ? [waiting] : []),
      ...(cache ? [`${cache.label.padEnd(10)}${cache.text}`] : []),
    ];
    const wide = e.props.bodyColumns >= 72;

    // Off a plan there is no window: the session's spend is the real bill.
    if (!five) {
      const spent = u.cost?.usd ?? 0;
      if (spent < 0.01 && lines.length === 0) return next(e);
      return (
        <Box flexDirection="column">
          <Box>
            <Text color="blue" bold>
              optimAIzr
            </Text>
            <Text dimColor>{`  ${usd(spent)} this session`}</Text>
          </Box>
          {lines[0] !== undefined && <Text dimColor>{lines[0]}</Text>}
          {lines[1] !== undefined && <Text dimColor>{lines[1]}</Text>}
          {lines[2] !== undefined && <Text dimColor>{lines[2]}</Text>}
        </Box>
      );
    }

    const [filled, empty] = bar(five.percentUsed, 16);
    const week = sevenDay(u.rateLimits);
    const note = wide ? windowNote(five, state.window, await $.clock.now()) : "";
    const weekNote = week && week.percentUsed >= 75 ? ` · 7d ${percent(week.percentUsed)}` : "";
    return (
      <Box flexDirection="column">
        <Box>
          <Text color="blue" bold>
            optimAIzr
          </Text>
          <Text>{"  "}</Text>
          {wide && <Text color={meterColor(five.percentUsed)}>{filled}</Text>}
          {wide && <Text dimColor>{`${empty}  `}</Text>}
          <Text color={meterColor(five.percentUsed)} bold>
            {percent(five.percentUsed)}
          </Text>
          <Text>{" of 5h"}</Text>
          <Text dimColor>{`${note}${weekNote}`}</Text>
        </Box>
        {lines[0] !== undefined && <Text dimColor>{lines[0]}</Text>}
        {lines[1] !== undefined && <Text dimColor>{lines[1]}</Text>}
        {lines[2] !== undefined && <Text dimColor>{lines[2]}</Text>}
      </Box>
    );
  });

  on("command.run", { command: "optimaizr" }, async ($, e) => {
    const list = await switches($).catch(() => []);
    const here = list.filter((o) => inProject(state.root, o.project));
    const arg = e.args.trim().toLowerCase();
    if (arg === "off" || arg === "on") {
      state.paused = arg === "off";
      void $.ui.invalidate("ui.render");
      return { text: pauseText(here, state.paused) };
    }
    // "pane" was its first name; it still works.
    if (arg === "hud" || arg === "pane") {
      await $.ui.open({ id: PANE, title: "optimAIzr HUD", focus: true });
      return { text: "Opened the optimAIzr HUD. Esc closes it." };
    }
    if (arg === "handoff") return { text: await handoff($) };
    if (arg) {
      return {
        text: "Use /optimaizr, /optimaizr hud, /optimaizr handoff, /optimaizr off or /optimaizr on.",
      };
    }

    await measure($).catch(() => undefined);
    const u = state.usage;
    const waiting = waitingNote();
    const cache = await cacheNow($);
    return {
      text: summary({
        ...(u?.cost ? { usd: u.cost.usd } : {}),
        requests: state.requests,
        startedAt: state.startedAt,
        limits: u?.rateLimits ?? [],
        ...(state.window ? { window: state.window } : {}),
        now: await $.clock.now(),
        switches: here,
        paused: state.paused,
        ...(state.saved !== undefined ? { saved: state.saved } : {}),
        held: state.held,
        turns: state.turnCosts,
        ...(waiting ? { note: waiting } : {}),
        ...(cache ? { cache } : {}),
      }),
    };
  });

  // The session at a glance: /optimaizr hud.
  on("ui.render", { component: "Pane", requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e);
    const u = state.usage;
    const five = fiveHour(u?.rateLimits);
    const week = sevenDay(u?.rateLimits);
    const now = await $.clock.now();
    const cols = e.props.bodyColumns;
    const width = Math.max(8, Math.min(24, cols - 22));

    const status = hudStatus();
    const saved = state.saved !== undefined && state.saved > 0 ? state.saved : 0;
    const cheaper =
      state.switchedWas > 0 ? Math.round((1 - state.switchedIs / state.switchedWas) * 100) : null;
    const spent = u?.cost ? u.cost.usd : null;
    // The rate covers what this mod has watched, from when it loaded.
    const hours = (now - state.startedAt) / 3_600_000;
    const rate =
      spent !== null && state.startUsd !== null && hours >= 1 / 30
        ? (spent - state.startUsd) / hours
        : null;
    const t = state.tokens;
    const ofWindow =
      five && spent !== null && state.startUsd !== null && state.startPct !== null
        ? windowShare(saved, {
            usd: spent - state.startUsd,
            pct: five.percentUsed - state.startPct,
          })
        : null;
    const cacheHits = t.input + t.read + t.write > 0 ? t.read / (t.input + t.read + t.write) : null;

    const gauge = (label: string, pct: number, note: string) => (
      <Box flexDirection="column">
        <Box>
          <Text dimColor>{`${label}  `}</Text>
          <Text color={meterColor(pct)}>{bar(pct, width)[0]}</Text>
          <Text dimColor>{bar(pct, width)[1]}</Text>
          <Text color={meterColor(pct)} bold>{`  ${percent(pct)}`}</Text>
        </Box>
        {note && <Text dimColor>{`    ${note}`}</Text>}
      </Box>
    );
    const turns = state.turnCosts;
    const top = Math.max(...turns, 0);
    const priciest = turns.indexOf(top) + 1;
    const lines = switchLines(activeSwitches());
    const waiting = waitingNote();
    const switchable = activeSwitches().length > 0 || waiting !== null;
    const cache = await cacheNow($);

    return (
      <Box flexDirection="column" gap={1}>
        <Box>
          <Text color="blue" bold>
            optimAIzr
          </Text>
          <Text color={status.color} bold>{`   ● ${status.text}`}</Text>
        </Box>

        <Box flexDirection="column">
          {state.switchedWas === 0 ? (
            <Text dimColor>no switch yet · press Y in optimaizr live</Text>
          ) : (state.saved ?? 0) < 0 ? (
            <Text color="yellow">{`reload ${usd(-(state.saved ?? 0))} not won back yet`}</Text>
          ) : (
            <Box>
              <Text color="green" bold>{`saved ${usd(saved)}`}</Text>
              {cheaper !== null && cheaper > 0 && (
                <Text color="green">{`  ${cheaper}% cheaper`}</Text>
              )}
              {ofWindow !== null && (
                <Text color="green">{`  ≈${share(ofWindow)} of your 5h window`}</Text>
              )}
            </Box>
          )}
          <Text dimColor>
            {[
              spent !== null ? `spent ${usd(spent)}` : null,
              rate !== null ? `${usd(rate)}/h` : null,
              `${state.requests} requests`,
              cacheHits !== null ? `cache ${percent(cacheHits * 100)}` : null,
            ]
              .filter(Boolean)
              .join(" · ")}
          </Text>
        </Box>

        {five && gauge("5h", five.percentUsed, paceNote(five, now))}
        {week && gauge("7d", week.percentUsed, "")}

        {turns.length > 1 && (
          <Box flexDirection="column">
            <Box>
              <Text dimColor>{"turns  "}</Text>
              {turns.map((v) => (
                <Text
                  color={v / (top || 1) > 0.66 ? "red" : v / (top || 1) > 0.33 ? "yellow" : "green"}
                >
                  {sparkline([v, top]).charAt(0)}
                </Text>
              ))}
            </Box>
            <Text dimColor>{`    priciest #${priciest} ${usd(top)} · last ${turns.length}`}</Text>
          </Box>
        )}

        {lines[0] !== undefined && <Text>{lines[0]}</Text>}
        {lines[1] !== undefined && <Text>{lines[1]}</Text>}
        {waiting && <Text color="yellow">{waiting}</Text>}
        {cache && <Text color="yellow">{`${cache.label.padEnd(10)}${cache.text}`}</Text>}
        {state.held > 0 && (
          <Text
            dimColor
          >{`guard  ${state.held} ${state.held === 1 ? "retry" : "retries"} held`}</Text>
        )}

        <Box gap={2}>
          {switchable && (
            <Button
              key="pause"
              label={state.paused ? "resume switch" : "pause switch"}
              hotkey="p"
              onPress={() => {
                state.paused = !state.paused;
                void $.ui.invalidate("ui.render");
              }}
            />
          )}
          <Text dimColor>Esc closes</Text>
        </Box>
      </Box>
    );
  });
};

/** Once a conversation passes LONG_CONTEXT, say what each request now re-reads. */
function longNote($: Api): void {
  const context = state.usage?.context.tokens ?? 0;
  const cost = carryCost(state.model, context);
  if (state.convo.long || context < LONG_CONTEXT || !cost) return;
  state.convo.long = true;
  void $.ui.toast(
    `optimAIzr: this conversation is past ${kTokens(LONG_CONTEXT)}. Each request re-reads all ${kTokens(context)} (${usd(cost.read)}). At a natural break, /optimaizr handoff, then /clear.`,
    { timeoutMs: 10_000 },
  );
}

/** The pill at the top of the HUD: what the mod is doing right now. */
function hudStatus(): { text: string; color: string } {
  if (state.paused) return { text: "paused", color: "yellow" };
  if (waitingNote()) return { text: "waiting", color: "yellow" };
  const model = activeSwitches().find((o) => !o.effort);
  if (model) {
    return { text: `on ${modelLabel(model.to)}${model.auto ? " (auto)" : ""}`, color: "green" };
  }
  const effort = activeSwitches().find((o) => o.effort);
  if (effort) return { text: `${effort.effort} effort`, color: "green" };
  return { text: "watching", color: "blue" };
}

/** The 5-hour window's outlook: when it runs out at this pace, or that it lasts. */
function paceNote(
  five: { resetsAt?: string; percentUsed: number; kind: string },
  now: number,
): string {
  const note = windowNote(five, state.window, now).replace(/^ · /, "");
  return note.startsWith("lasts") ? `${note} ✓` : note;
}

/** Why a switch for this conversation is waiting, if one is. */
function waitingNote(): string | null {
  const w = state.waiting;
  if (!w || state.paused || state.convo.loaded.has(w.o.to)) return null;
  const back = Number.isFinite(w.payback)
    ? `pays back in ~${Math.ceil(w.payback)} requests`
    : "would not pay back";
  return `waiting   ${describeSwitch(w.o)} · reload ${usd(w.reload)} ${back} · subagents switch now`;
}

/** Switches that moved a request here and are still in overrides.json. */
function activeSwitches(): Override[] {
  return [...state.applied.values()].filter((a) =>
    state.overrides.some((o) => slotOf(o) === slotOf(a) && o.to === a.to),
  );
}

/** The band's lines under the window: the model switch, then the effort switch. */
function switchLines(applied: readonly Override[]): string[] {
  const back = state.paused ? "/optimaizr on to switch again" : "harder task? /optimaizr off";
  const saved =
    !state.paused && state.saved !== undefined && state.saved >= 0.005
      ? ` · saved ${usd(state.saved)}`
      : "";
  const lines: string[] = [];
  // While the main conversation waits, the waiting line says what subagents do.
  const model = waitingNote() ? undefined : applied.find((o) => !o.effort);
  if (model) {
    lines.push(
      `${state.paused ? "paused  " : "switched"}  ${describeSwitch(model)}${model.auto ? " (auto)" : ""}${saved} · ${back}`,
    );
  }
  const effort = applied.find((o) => o.effort);
  if (effort) {
    lines.push(`${state.paused ? "paused  " : "effort  "}  ${describeSwitch(effort)} · ${back}`);
  }
  return lines;
}

/** The line left in the conversation the first time a switch moves a request. */
function switchNote(o: Override, sub: boolean): string {
  const who = sub || o.subagent === true ? "this session's subagents" : "this session";
  const how = o.auto ? `${o.rule}, automatically` : o.rule;
  if (o.effort) {
    return (
      `Lowered ${who} to ${o.effort} effort on ${modelLabel(o.from)} (${how}). ` +
      `Harder task? /optimaizr off goes back to its own effort.`
    );
  }
  return (
    `Switched ${who} from ${modelLabel(o.from)} to ${modelLabel(o.to)} (${how}). ` +
    `Harder task? /optimaizr off goes back to ${modelLabel(o.from)}.`
  );
}

function pauseText(here: readonly Override[], paused: boolean): string {
  const o = here.find((x) => !x.effort) ?? here[0];
  if (!o) return "No switch is active in this project.";
  if (o.effort) {
    return paused
      ? `Switches are off for this session: requests use their own effort again. ` +
          `/optimaizr on lowers it to ${o.effort} again; optimaizr undo ${o.rule} removes it everywhere.`
      : `Switches are on again for this session: requests use ${o.effort} effort.`;
  }
  return paused
    ? `Switches are off for this session: requests go to ${modelLabel(o.from)} again. ` +
        `/optimaizr on switches back to ${modelLabel(o.to)}; ` +
        `optimaizr undo ${o.rule} removes it everywhere.`
    : `Switches are on again for this session: requests go to ${modelLabel(o.to)}.`;
}

files.hooks/meter.ts:
// Pure helpers for register.tsx. Nothing here touches `$`, so the figures the
// band, the spinner and /optimaizr show can be tested on their own.

import { PRICES, type Price } from "./prices.ts";

export type RateLimit = { kind: string; percentUsed: number; resetsAt?: string };

/** One reading of the 5-hour window: when, and how full. */
export type Sample = { t: number; pct: number };

/** The readings of one 5-hour window, kept in $.store so every session shares them. */
export type Window = { resetsAt: string; samples: Sample[] };

/** An entry of ~/.optimaizr/overrides.json, as `optimaizr live` writes it. */
export type Override = {
  rule: string;
  source?: string;
  project: string;
  subagent?: boolean;
  from: string;
  to: string;
  /** An effort switch: the same model, asked to think less. */
  effort?: string;
  /** Applied by `optimaizr live --auto`, with no one pressing Y. */
  auto?: boolean;
};

/** A request's token counts, as the API reports them. */
export type Tokens = {
  input_tokens: number;
  output_tokens: number;
  cache_read_input_tokens: number;
  cache_creation_input_tokens: number;
};

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;

export const fiveHour = (limits: readonly RateLimit[] | undefined) =>
  limits?.find((l) => l.kind === "five_hour");

export const sevenDay = (limits: readonly RateLimit[] | undefined) =>
  limits?.find((l) => l.kind === "seven_day");

/**
 * The meters as the session file carries them, so `optimaizr profile` and
 * `optimaizr live` can show Claude Code's real windows. Undefined when neither
 * meter is reported (an API-key session has none).
 */
export function windowsOf(limits: readonly RateLimit[] | undefined, at: number) {
  const pick = (l: RateLimit | undefined) =>
    l ? { percentUsed: l.percentUsed, ...(l.resetsAt ? { resetsAt: l.resetsAt } : {}) } : undefined;
  const five = pick(fiveHour(limits));
  const seven = pick(sevenDay(limits));
  if (!five && !seven) return undefined;
  return {
    at: new Date(at).toISOString(),
    ...(five ? { fiveHour: five } : {}),
    ...(seven ? { sevenDay: seven } : {}),
  };
}

/** `claude-opus-5-5[1m]` and `claude-opus-5-5-20260915` are `claude-opus-5-5`. */
export function baseModel(id: string): string {
  return id
    .toLowerCase()
    .replace(/\[[^\]]*\]$/, "")
    .replace(/-\d{8}$/, "");
}

/** `claude-sonnet-5-5` is `Sonnet 5.5`; an id it can't read is shown as given. */
export function modelLabel(id: string): string {
  const m = /^claude-(opus|sonnet|haiku|fable)-(\d+)(?:-(\d{1,2}))?$/.exec(baseModel(id));
  if (!m) return id;
  const family = m[1]!;
  return `${family[0]!.toUpperCase()}${family.slice(1)} ${m[2]}${m[3] ? `.${m[3]}` : ""}`;
}

export function usd(n: number): string {
  return `$${n.toFixed(2)}`;
}

export function percent(n: number): string {
  return `${Math.round(n)}%`;
}

/** `45m`, `2h 05m`. */
export function duration(ms: number): string {
  const m = Math.max(1, Math.round(ms / MINUTE));
  return m < 60 ? `${m}m` : `${Math.floor(m / 60)}h ${String(m % 60).padStart(2, "0")}m`;
}

/** Local wall-clock time, `01:00`. */
export function clock(iso: string): string {
  const d = new Date(iso);
  return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
}

/**
 * A saving as a share of the 5-hour window, from how far the window moved
 * against what was spent meanwhile. Null until it has moved a whole point;
 * other sessions on the account move it too, so it is an estimate.
 */
export function windowShare(saved: number, spent: { usd: number; pct: number }): number | null {
  if (spent.pct < 1 || spent.usd <= 0 || saved <= 0) return null;
  return saved / (spent.usd / spent.pct);
}

/** `0.4%`, `2.1%`, `12%`. */
export function share(pct: number): string {
  return pct < 10 ? `${pct.toFixed(1)}%` : `${Math.round(pct)}%`;
}

/** The meter's colour as the window fills: calm, then a warning, then urgent. */
export function meterColor(pct: number): "green" | "yellow" | "red" {
  return pct < 60 ? "green" : pct < 85 ? "yellow" : "red";
}

/** A sparkline of turn costs, one cell each, scaled to the largest. */
export function sparkline(values: readonly number[]): string {
  const cells = "▁▂▃▄▅▆▇█";
  const top = Math.max(...values, 0);
  return values.map((v) => cells[top > 0 ? Math.min(7, Math.round((v / top) * 7)) : 0]).join("");
}

/** The window levels that earn a toast, and the session savings that do. */
export const WINDOW_ALERTS = [80, 95];
export const SAVED_MILESTONES = [0.5, 1, 2, 5, 10, 20, 50];

/** The highest threshold crossed going from `was` to `now`, if any. */
export function crossed(thresholds: readonly number[], was: number, now: number): number | null {
  const hit = thresholds.filter((t) => was < t && now >= t);
  return hit.length > 0 ? hit[hit.length - 1]! : null;
}

/** The filled and empty halves of a meter `width` cells wide. */
export function bar(pct: number, width: number): [string, string] {
  const n = Math.round((Math.min(100, Math.max(0, pct)) / 100) * width);
  return ["█".repeat(n), "░".repeat(width - n)];
}

export function projectName(p: string): string {
  return p.split(/[\\/]/).filter(Boolean).slice(-1)[0] ?? p;
}

/** `shop-api subagents: Opus 5.5 → Sonnet 5.5`, or `shop-api: Opus 5.5 at low effort`. */
export function describeSwitch(o: Override): string {
  const who = o.subagent === true ? " subagents" : o.subagent === false ? " main" : "";
  const what = o.effort
    ? `${modelLabel(o.from)} at ${o.effort} effort`
    : `${modelLabel(o.from)} → ${modelLabel(o.to)}`;
  return `${projectName(o.project)}${who}: ${what}`;
}

function isOverride(v: unknown): v is Override {
  const o = v as Override;
  return (
    typeof o === "object" &&
    o !== null &&
    o.source === "claude-code" &&
    typeof o.rule === "string" &&
    typeof o.project === "string" &&
    typeof o.from === "string" &&
    typeof o.to === "string" &&
    (o.subagent === undefined || typeof o.subagent === "boolean") &&
    (o.effort === undefined || EFFORTS.includes(o.effort)) &&
    (o.auto === undefined || typeof o.auto === "boolean")
  );
}

/** Claude Code's entries of overrides.json; anything unreadable is no switch at all. */
export function parseOverrides(text: string): Override[] {
  try {
    const file = JSON.parse(text) as { overrides?: unknown };
    return Array.isArray(file?.overrides) ? file.overrides.filter(isOverride) : [];
  } catch {
    return [];
  }
}

const slash = (p: string) => p.replace(/\\/g, "/").replace(/\/+$/, "");

/** Is `cwd` the project, or a folder inside it? */
export function inProject(cwd: string, project: string): boolean {
  const c = slash(cwd);
  const p = slash(project);
  return c === p || c.startsWith(`${p}/`);
}

const covers = (o: Override, req: { cwd: string; model: string; subagent: boolean }) =>
  inProject(req.cwd, o.project) &&
  (o.subagent === undefined || o.subagent === req.subagent) &&
  baseModel(o.from) === baseModel(req.model);

/** The model switch for one request: its project, agent and model. */
export function switchFor(
  list: readonly Override[],
  req: { cwd: string; model: string; subagent: boolean },
): Override | undefined {
  return list.find((o) => !o.effort && covers(o, req) && baseModel(o.to) !== baseModel(req.model));
}

/** Lowest first. A number, or a level not listed, is never lowered. */
const EFFORTS: readonly string[] = ["low", "medium", "high", "xhigh", "max"];

/** The effort switch for one request, only when it asks for less than the request does. */
export function effortFor(
  list: readonly Override[],
  req: { cwd: string; model: string; subagent: boolean; effort?: string | number },
): Override | undefined {
  const now = typeof req.effort === "string" ? EFFORTS.indexOf(req.effort) : -1;
  return list.find(
    (o) => o.effort !== undefined && covers(o, req) && EFFORTS.indexOf(o.effort) < now,
  );
}

const priceOf = (model: string): Price | undefined => PRICES[baseModel(model)];

/**
 * What a request's tokens cost at a model's rates. `warm`: its cache writes would
 * have been reads. `hour`: the main conversation caches for an hour, at 2x input;
 * subagents for 5 minutes, at 1.25x, as the engine prices them.
 */
export function costAt(
  model: string,
  t: Tokens,
  opts: { warm?: boolean; hour?: boolean } = {},
): number | null {
  const p = priceOf(model);
  if (!p) return null;
  const write = opts.warm ? p.cacheRead : opts.hour ? p.cacheWrite1h : p.cacheWrite;
  return (
    (t.input_tokens * p.input +
      t.output_tokens * p.output +
      t.cache_read_input_tokens * p.cacheRead +
      t.cache_creation_input_tokens * write) /
    1_000_000
  );
}

/**
 * What a switched request saved: the same tokens at the original model's rates,
 * less what they cost on the new one. The first request on the new model writes
 * the conversation to its cache, where the original model would have read it,
 * so that one is priced warm and can come out negative.
 */
/** What reloading a conversation of `contextTokens` into the new model's cache costs, over reading it on the old one. */
export function reloadCost(o: Override, contextTokens: number): number | null {
  const from = priceOf(o.from);
  const to = priceOf(o.to);
  if (!from || !to) return null;
  return (contextTokens * (to.cacheWrite1h - from.cacheRead)) / 1_000_000;
}

// Switching a conversation under way waits until the reload is won back within this many requests.
export const PAYBACK_REQUESTS = 10;

/**
 * Requests until a mid-conversation switch pays for its reload, from this
 * session's average request. Infinity when a request saves nothing.
 */
export function paybackRequests(o: Override, contextTokens: number, avg: Tokens): number {
  const reload = reloadCost(o, contextTokens);
  const was = costAt(o.from, avg, { hour: true });
  const is = costAt(o.to, avg, { hour: true });
  if (reload === null || was === null || is === null) return Infinity;
  if (reload <= 0) return 0;
  return was > is ? reload / (was - is) : Infinity;
}

export function savedBy(o: Override, t: Tokens, first: boolean, hour = true): number | null {
  const was = costAt(o.from, t, { warm: first, hour });
  const is = costAt(o.to, t, { hour });
  return was === null || is === null ? null : was - is;
}

/** `340K`. */
export function kTokens(n: number): string {
  return `${Math.round(n / 1_000)}K`;
}

// Below this, writing the conversation again costs about what a fresh start does.
export const COLD_MIN_CONTEXT = 50_000;
// Past this, each request re-reads far more than the work in front of it needs.
export const LONG_CONTEXT = 200_000;
// The band counts down this long before the cache expires.
export const COUNTDOWN_MS = 15 * MINUTE;
// One toast this close to expiry, when coming back would cost at least EXPIRY_TOAST_USD.
export const EXPIRY_TOAST_MS = 5 * MINUTE;
export const EXPIRY_TOAST_USD = 0.5;

/**
 * What carrying the conversation costs on one request: read from a warm cache,
 * or written to it again at the 1-hour rate once it expired.
 */
export function carryCost(
  model: string,
  contextTokens: number,
): { read: number; rewrite: number } | null {
  const p = priceOf(model);
  if (!p) return null;
  return {
    read: (contextTokens * p.cacheRead) / 1_000_000,
    rewrite: (contextTokens * p.cacheWrite1h) / 1_000_000,
  };
}

/**
 * What to say about the conversation's cache while the prompt waits: a
 * countdown before it expires, what coming back costs after, or what each
 * request re-reads once the conversation is long. Null when none applies.
 */
export function cacheNote(c: {
  model: string;
  context: number;
  idleMs: number;
  ttlMs: number;
}): { label: "cache" | "context"; text: string } | null {
  if (c.context < COLD_MIN_CONTEXT) return null;
  const cost = carryCost(c.model, c.context);
  if (!cost) return null;
  const left = c.ttlMs - c.idleMs;
  const size = kTokens(c.context);
  if (left <= 0) {
    return {
      label: "cache",
      text: `expired · the next message writes ${size} again (${usd(cost.rewrite)})`,
    };
  }
  if (left <= COUNTDOWN_MS) {
    return {
      label: "cache",
      text: `warm ${duration(left)} more, then ${size} is written again (${usd(cost.rewrite)}) · leaving? /optimaizr handoff`,
    };
  }
  if (c.context >= LONG_CONTEXT) {
    return {
      label: "context",
      text: `${size} · each request re-reads it (${usd(cost.read)}) · fresh start: /optimaizr handoff`,
    };
  }
  return null;
}

// A handoff note is used once, by a conversation started within this long.
export const HANDOFF_TTL_MS = 12 * HOUR;

/** What Claude is asked for: a note a fresh conversation can start from. */
export const HANDOFF_PROMPT =
  "Write a handoff note so a fresh conversation can carry on this work without this one. " +
  "Plain text, under 250 words, in four short parts: what changed (files and why), " +
  "what was decided, what is still open, and what to check first. Name exact paths, " +
  "commands and errors. No preamble, and no tool calls.";

export type Handoff = {
  version: 1;
  root: string;
  /** The session and conversation it was written in, which never read it back. */
  session: string;
  conversation: number;
  at: string;
  text: string;
  usedAt?: string;
};

export function isHandoff(v: unknown): v is Handoff {
  const h = v as Handoff;
  return (
    typeof h === "object" &&
    h !== null &&
    h.version === 1 &&
    typeof h.root === "string" &&
    typeof h.session === "string" &&
    typeof h.conversation === "number" &&
    typeof h.at === "string" &&
    typeof h.text === "string"
  );
}

/** One note per project: `/work/shop-api` keeps `work-shop-api.json`. */
export function handoffFile(dir: string, root: string): string {
  const key =
    slash(root)
      .replace(/[^A-Za-z0-9._-]+/g, "-")
      .replace(/^-+|-+$/g, "") || "root";
  return `${dir}/mod/handoffs/${key}.json`;
}

/**
 * The note a new conversation should start from, if one is waiting: same
 * project, unused, recent, and written in another conversation.
 */
export function handoffFor(
  v: unknown,
  at: { root: string; session: string; conversation: number; now: number },
): Handoff | null {
  if (!isHandoff(v) || v.usedAt || slash(v.root) !== slash(at.root)) return null;
  if (v.session === at.session && v.conversation === at.conversation) return null;
  const age = at.now - Date.parse(v.at);
  return age >= 0 && age <= HANDOFF_TTL_MS ? v : null;
}

/** The context block the next conversation reads. */
export function handoffBlock(h: Handoff): string {
  return (
    `A handoff note from the previous conversation in this project, written by Claude at ` +
    `${clock(h.at)} and saved by optimAIzr. Check it against the code before relying on it.\n\n` +
    h.text.trim()
  );
}

export function isWindow(v: unknown): v is Window {
  const w = v as Window;
  return (
    typeof w === "object" &&
    w !== null &&
    typeof w.resetsAt === "string" &&
    Array.isArray(w.samples)
  );
}

/** Add a reading. A new window, or one that went down, starts the history over. */
export function record(w: Window | undefined, limit: RateLimit, t: number): Window {
  const resetsAt = limit.resetsAt ?? "";
  const pct = limit.percentUsed;
  const last = w?.samples.at(-1);
  if (!w || w.resetsAt !== resetsAt || (last && pct < last.pct)) {
    return { resetsAt, samples: [{ t, pct }] };
  }
  if (last && last.pct === pct) return w;
  return { resetsAt, samples: [...w.samples, { t, pct }].slice(-120) };
}

/**
 * When the window runs out at the pace of the last hour, as epoch ms. Null
 * until there are 10 minutes and one point of use to go on.
 */
export function runsOutAt(w: Window): number | null {
  const last = w.samples.at(-1);
  const base = w.samples.find((s) => last && s.t >= last.t - HOUR);
  if (!last || !base) return null;
  const span = last.t - base.t;
  const used = last.pct - base.pct;
  if (span < 10 * MINUTE || used < 1) return null;
  return last.t + ((100 - last.pct) / used) * span;
}

/** What follows the percent in the band: the pace, then the reset. */
export function windowNote(five: RateLimit, w: Window | undefined, now: number): string {
  const resets = five.resetsAt ? clock(five.resetsAt) : null;
  const end = w && w.resetsAt === (five.resetsAt ?? "") ? runsOutAt(w) : null;
  const resetAt = five.resetsAt ? Date.parse(five.resetsAt) : null;
  if (end !== null && resetAt !== null && end >= resetAt) return ` · lasts to the ${resets} reset`;
  const pace = end === null ? "" : ` · ~${duration(Math.max(0, end - now))} left at this pace`;
  return `${pace}${resets ? ` · resets ${resets}` : ""}`;
}

/** What the spinner shows after its word: the switched model, the turn so far, the window. */
export function meterText(m: {
  usd: number | null;
  five?: RateLimit;
  model?: string;
  saved?: number;
}): string {
  const parts: string[] = [];
  if (m.model) parts.push(m.model);
  if (m.usd !== null && m.usd >= 0.005) parts.push(usd(m.usd));
  if (m.saved !== undefined && m.saved >= 0.005) parts.push(`saved ${usd(m.saved)}`);
  if (m.five) parts.push(`${percent(m.five.percentUsed)} of 5h`);
  return parts.length > 0 ? ` · ${parts.join(" · ")}` : "";
}

const plural = (n: number, one: string, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;

/**
 * The line under an answer. Claude Code puts the plugin's name in front of it.
 * A switched turn leads with what it saved, so the difference reads first.
 */
export function turnLine(t: {
  usd: number;
  calls: number;
  /** The model switch this turn ran under: labels, and what it saved (null: unpriced). */
  switched?: { from: string; to: string; saved: number | null };
  effort?: string;
  held?: number;
  before?: number;
  after?: number;
}): string {
  const parts: string[] = [];
  const s = t.switched;
  if (s && s.saved !== null && s.saved >= 0.005) {
    parts.push(`saved ${usd(s.saved)} vs ${s.from}`, `this turn ${usd(t.usd)} on ${s.to}`);
  } else if (s) {
    parts.push(`this turn ${usd(t.usd)} on ${s.to}`);
  } else {
    parts.push(`this turn ${usd(t.usd)}${t.effort ? ` at ${t.effort} effort` : ""}`);
  }
  parts.push(plural(t.calls, "request"));
  if (s && s.saved !== null && s.saved <= -0.005) {
    parts.push(`${usd(-s.saved)} more than ${s.from} once, to load the conversation`);
  }
  if (t.held) parts.push(`${plural(t.held, "retry", "retries")} held`);
  if (t.before !== undefined && t.after !== undefined) {
    parts.push(`5h ${percent(t.before)} → ${percent(t.after)}`);
  }
  return parts.join(" · ");
}

/** What /optimaizr prints. */
export function summary(s: {
  usd?: number;
  requests: number;
  startedAt: number;
  limits: readonly RateLimit[];
  window?: Window;
  now: number;
  switches: readonly Override[];
  paused?: boolean;
  /** Net saving of this session's switched requests, when any were priced. */
  saved?: number;
  held?: number;
  /** What each recent turn cost, oldest first. */
  turns?: readonly number[];
  /** Why a switch for this conversation is waiting, when one is. */
  note?: string;
  /** The conversation's cache, when there is something to say about it. */
  cache?: { label: string; text: string };
}): string {
  const rows: Array<[string, string]> = [];
  const onPlan = s.limits.length > 0;
  const spent = s.usd === undefined ? "not reported" : usd(s.usd);
  rows.push([
    "Spend",
    `${spent}${onPlan ? " at API rates" : ""} over ${plural(s.requests, "request")} since ${clock(new Date(s.startedAt).toISOString())}`,
  ]);
  if (s.saved !== undefined && s.saved < 0) {
    rows.push([
      "Saved",
      `not yet: reloading the conversation cost ${usd(-s.saved)} more than the switch has saved so far`,
    ]);
  } else if (s.saved !== undefined) {
    rows.push([
      "Saved",
      `${usd(s.saved)} by switching models: the same tokens at the original model's rates, less what they cost`,
    ]);
  }
  if (s.held) rows.push(["Guard", `${plural(s.held, "retry", "retries")} held`]);
  if (s.turns && s.turns.length > 1) {
    rows.push([
      "Turns",
      `${sparkline(s.turns)}  last ${s.turns.length}, up to ${usd(Math.max(...s.turns))}`,
    ]);
  }
  const five = fiveHour(s.limits);
  if (five)
    rows.push(["5h window", `${percent(five.percentUsed)}${windowNote(five, s.window, s.now)}`]);
  const week = sevenDay(s.limits);
  if (week) {
    const resets = week.resetsAt
      ? ` · resets ${new Date(week.resetsAt).toDateString().slice(0, 3)} ${clock(week.resetsAt)}`
      : "";
    rows.push(["7d window", `${percent(week.percentUsed)}${resets}`]);
  }
  if (s.cache) rows.push([s.cache.label === "cache" ? "Cache" : "Context", s.cache.text]);
  for (const [i, o] of s.switches.entries()) {
    const how = s.paused
      ? "off in this session: /optimaizr on"
      : `/optimaizr off here, optimaizr undo ${o.rule} everywhere`;
    rows.push([i === 0 ? "Switch" : "", `${describeSwitch(o)} · ${how}`]);
  }
  if (s.switches.length === 0) rows.push(["Switch", "none: accept one with Y in optimaizr live"]);
  if (s.note) rows.push(["", s.note.replace(/^waiting\s+/, "waiting: ")]);
  return rows.map(([k, v]) => `${k.padEnd(11)}${v}`).join("\n");
}

